        $bar->start();

        foreach ($uatNumbers as $key => $number) {
            $uatTransaction = Transaction::where('receipt_number', $number)
                ->where('branch_id', 14)
                ->first();

            $prodTransaction = Transaction::where('receipt_number', $prodNumbers[$key])
                ->where('branch_id', 14)
                ->first();

            $items = $uatTransaction->items;

            // Delete old records first
            DB::statement("DELETE FROM transactional_db.orders WHERE branch_id = 14 AND transaction_id = ?", [$prodTransaction->transaction_id]);

            foreach ($items as $item) {
                $itemArray = $item->toArray();
                
                // Remove id column
                unset($itemArray['id']);
                
                // Replace transaction_id with prod transaction
                $itemArray['transaction_id'] = $prodTransaction->transaction_id;
                
                // Get column names and values
                $columns = array_keys($itemArray);
                $values = array_values($itemArray);
                
                // Build INSERT statement
                $columnList = '`' . implode('`, `', $columns) . '`';
                $valueList = implode(', ', array_map(function($val, $col) {
                    if (is_null($val)) {
                        return 'NULL';
                    }
                    
                    // Convert ISO 8601 timestamps to MySQL datetime format for created_at and updated_at
                    if (($col === 'created_at' || $col === 'updated_at') && $val) {
                        // Convert from 2026-01-12T14:16:19.000000Z to 2026-01-12 22:03:42
                        $val = substr($val, 0, 10) . ' ' . substr($val, 11, 8);
                    }
                    
                    if (is_numeric($val) && !is_string($val)) {
                        return $val;
                    }
                    return "'" . str_replace("'", "''", $val) . "'";
                }, $values, $columns));
                
                $sql = "INSERT INTO transactional_db.orders ($columnList) VALUES ($valueList);";
                
                // Execute directly
                DB::statement($sql);
            }

            $bar->advance();
        }

        $bar->finish();
        $this->newLine();
        $this->info("Orders inserted directly to database successfully!");
